import{freshBag,cleanBag,putInBag}from'./inventory62.js?v=62';
import{BALANCE}from'./balance.js?v=48';
import{SEED_CATALOG,seedStage,seedStages,seedCounts}from'./seed-shop.js?v=62';
export const STARTER_CELL=[14,8];
export const referenceStarter=(s,p)=>p.id===s.loop.starterId&&p.c===STARTER_CELL[0]&&p.r===STARTER_CELL[1];
export const KEY='suming-cozy-island-v1';
export const FURNITURE={seedplot:{name:'씨앗 자리',max:24},bench:{name:'쿠션 벤치',max:3},pot:{name:'토분 화분',max:10},tree:{name:'사과나무',max:4},bowl:{name:'모모 물그릇',max:2},pond:{name:'수련 연못',max:2},table:{name:'티 테이블',max:3},cushion:{name:'폭신 방석',max:4},lamp:{name:'정원등',max:5},path:{name:'디딤돌',max:20},fence:{name:'나무 울타리',max:10},field:{name:'텃밭',max:2}};
// Harvest receipts go to inventory; only sales credit shells. The legacy earned field quotes sale value when harvested is present.
export const CROPS={carrot:{name:'당근',...BALANCE.crops.carrot},potato:{name:'감자',...BALANCE.crops.potato},strawberry:{name:'딸기',...BALANCE.crops.strawberry}};
export const LIVESTOCK={hen:{name:'암탉',sprite:'hen',...BALANCE.animals.hen},duck:{name:'오리',sprite:'duck',...BALANCE.animals.duck},sheep:{name:'양',sprite:'sheep',...BALANCE.animals.sheep},cow:{name:'젖소',sprite:'cow',...BALANCE.animals.cow},llama:{name:'라마',sprite:'llama',...BALANCE.animals.llama}};
export const ITEM_PRICES=BALANCE.furniture;
export const FEED=BALANCE.feed;
export const ANIMAL_STAGES=Object.fromEntries(Object.entries(BALANCE.animals).map(([k,v])=>[k,v.stages]));
export const animalStage=a=>Math.max(1,Math.min(ANIMAL_STAGES[a.kind]||5,Number(a.stage)||1));
export const mature=a=>animalStage(a)===ANIMAL_STAGES[a.kind];
export const MAX_ANIMALS=8,MAX_EXTRA=30;
export const limit=(s,kind)=>FURNITURE[kind].max+(s.extra?.[kind]||0);
export const ripe=(p,now=Date.now())=>!!p.crop&&now-p.sown>=CROPS[p.crop].ms;
export const productReady=(a,now=Date.now())=>mature(a)&&a.fed===true&&now-a.at>=LIVESTOCK[a.kind].ms;
let terrain=null;
// Walkable tiles of the current sky island; null keeps the classic round garden.
export function setTerrain(cells){terrain=Array.isArray(cells)&&cells.length?new Set(cells.filter(c=>Array.isArray(c)&&c.length===2).map(c=>c.join(','))):null;}
export function terrainCells(){if(terrain)return[...terrain].map(k=>k.split(',').map(Number));const out=[];for(let r=0;r<9;r++)for(let c=0;c<9;c++)if(validCell(c,r))out.push([c,r]);return out;}
export const SEEDS={daisy:'데이지',tulip:'튤립',lavender:'라벤더'};
export const CLOSET={skin:['cream','honey','cocoa'],hair:['bob','wave','short','twin'],hairColor:['chestnut','black','caramel','rose'],top:['sailor','cardigan','tee','hoodie','blouse','overall'],bottom:['shorts','skirt','trousers','pleats'],shoes:['cream','brown','pink','sage'],hat:['none','straw','beret','bow'],accessory:['none','bag','scarf','glasses']};
export const LABELS={cream:'크림',honey:'허니',cocoa:'코코아',bob:'단정한 단발',wave:'물결 머리',short:'산뜻한 숏컷',twin:'양갈래',chestnut:'밤색',black:'흑갈색',caramel:'카라멜',rose:'로즈 브라운',sailor:'바다 세일러',cardigan:'봄 가디건',tee:'산책 티셔츠',hoodie:'포근 후디',blouse:'리본 블라우스',overall:'정원 멜빵',shorts:'반바지',skirt:'꽃잎 스커트',trousers:'면바지',pleats:'주름 치마',brown:'브라운',pink:'딸기 우유',sage:'세이지',none:'착용 안 함',straw:'밀짚 모자',beret:'딸기 베레모',bow:'리본 머리띠',bag:'작은 크로스백',scarf:'체크 스카프',glasses:'동그란 안경'};
export const defaultOutfit=()=>({skin:'cream',hair:'bob',hairColor:'chestnut',top:'sailor',bottom:'shorts',shoes:'brown',hat:'none',accessory:'bag'});
export function validCell(c,r){if(terrain)return Number.isInteger(c)&&Number.isInteger(r)&&terrain.has(c+','+r);return Number.isInteger(c)&&Number.isInteger(r)&&c>=0&&r>=0&&c<9&&r<9&&(c-4)**2+(r-4)**2<=20&&!(c>=1&&c<=3&&r>=1&&r<=3);}
export function fresh(){return{loop:{v:1,started:false,firstApple:false,level:1,starterId:null},inventory:freshBag(),feedStock:{feed:0,milk:0},seedStock:{},v:1,next:9,avatar:[4,7],outfit:defaultOutfit(),items:[{id:1,kind:'bench',c:2,r:6,rot:0},{id:2,kind:'pot',c:5,r:3,rot:0},{id:3,kind:'pot',c:6,r:4,rot:0},{id:4,kind:'tree',c:7,r:2,rot:0},{id:5,kind:'bowl',c:5,r:7,rot:0},{id:6,kind:'pond',c:7,r:5,rot:0},{id:7,kind:'path',c:4,r:4,rot:0},{id:8,kind:'path',c:4,r:5,rot:0}],flowers:[],hearts:0,petAt:0,fruitAt:0,apples:0,water:false,welcomed:false,theme:'day',tasks:{},looks:[],extra:{},animals:[]};}
export function growth(p,now=Date.now()){return p.seed?Math.min(1,Math.max(0,(Math.max(0,now-p.planted)+(p.boost||0))/90000)):0;}
export const passable=(s,c,r)=>validCell(c,r)&&!s.items.some(p=>p.c===c&&p.r===r&&p.kind!=='path')&&!(s.animals||[]).some(a=>a.c===c&&a.r===r);
export function route(s,start,goal){if(!Array.isArray(goal)||goal.length!==2||!passable(s,...goal))return[];const q=[[start]],seen=new Set([start.join(',')]);while(q.length){const path=q.shift(),[c,r]=path.at(-1);if(c===goal[0]&&r===goal[1])return path;for(const n of [[c+1,r],[c-1,r],[c,r+1],[c,r-1]]){const k=n.join(',');if(!seen.has(k)&&passable(s,...n)){seen.add(k);q.push([...path,n]);}}}return[];}
export function approach(s,start,p){const targets=[[p.c,p.r+1],[p.c+1,p.r],[p.c-1,p.r],[p.c,p.r-1]].map(t=>route(s,start,t)).filter(t=>t.length);return targets.sort((a,b)=>a.length-b.length)[0]||[];}
export function apply(s,e,now=Date.now()){const n=structuredClone(s),p=n.items.find(p=>p.id===e.id),fail=why=>({ok:false,why,state:s});
 if(e.type==='buy-feed'){if(!FEED[e.food])return fail('없는 먹이예요.');if(n.feedStock[e.food]>=999)return fail('먹이 주머니가 가득 찼어요.');n.feedStock[e.food]++;}
 else if(e.type==='pet-animal'){const a=n.animals.find(x=>x.id===e.id);if(!a||Math.abs(s.avatar[0]-a.c)+Math.abs(s.avatar[1]-a.r)!==1)return fail('먼저 동물 가까이 가 주세요.');if(a.petAt&&now-a.petAt<10000)return fail('친구가 잠깐 쉬고 있어요.');a.petAt=now;n.hearts=Math.min(10,n.hearts+1);n.tasks.friend=true;}
 else if(e.type==='feed'){const a=n.animals.find(x=>x.id===e.id);if(!a||Math.abs(s.avatar[0]-a.c)+Math.abs(s.avatar[1]-a.r)!==1)return fail('먼저 동물 가까이 가 주세요.');if(!FEED[e.food]||!n.feedStock[e.food])return fail('상점에서 먹이를 구매해 주세요.');if(a.fed&&now-a.at<LIVESTOCK[a.kind].ms)return fail('아직 배가 불러요.');if(productReady(a,now))return fail('준비된 선물을 먼저 수확해 주세요.');n.feedStock[e.food]--;if(a.fed&&!mature(a))a.stage=animalStage(a)+1;a.fed=true;a.at=now;}
 else if(e.type==='buy-seed'){if(!SEED_CATALOG[e.seedKind])return fail('없는 씨앗이에요.');if((n.seedStock[e.seedKind]||0)>=999)return fail('씨앗 주머니가 가득 찼어요.');n.seedStock[e.seedKind]=(n.seedStock[e.seedKind]||0)+1;}
 else if(e.type==='plant-seed'){if(!SEED_CATALOG[e.seedKind]||!n.seedStock[e.seedKind])return fail('먼저 씨앗을 구매해 주세요.');const placed=apply(n,{type:'place',kind:'seedplot',c:e.c,r:e.r},now);if(!placed.ok)return fail(placed.why);const plant=placed.state.items.at(-1);plant.seedKind=e.seedKind;plant.seedAt=now;plant.seedBoost=0;plant.seedWatered=0;placed.state.seedStock[e.seedKind]--;if(!placed.state.seedStock[e.seedKind])delete placed.state.seedStock[e.seedKind];return placed;}
 else if(e.type==='tend-seed'||e.type==='harvest-seed'){if(!p?.seedKind||Math.abs(s.avatar[0]-p.c)+Math.abs(s.avatar[1]-p.r)!==1)return fail('먼저 작물 가까이 가 주세요.');const v=SEED_CATALOG[p.seedKind];if(e.type==='tend-seed'){if(seedStage(p,now)===seedStages(p.seedKind))return fail('이제 수확할 수 있어요.');if(p.seedWatered&&now-p.seedWatered<10000)return fail('물이 스며들고 있어요. 잠시 기다려 주세요.');p.seedWatered=now;p.seedBoost=(p.seedBoost||0)+15000;}else{if(seedStage(p,now)<seedStages(p.seedKind))return fail('마지막 단계에서 수확할 수 있어요.');if(v.type==='tree'){p.seedAt=now-v.ms/2;p.seedBoost=0;p.seedWatered=0;}else n.items=n.items.filter(x=>x.id!==p.id);n.tasks.reaped=true;if(p.seedKind==='apple'&&!n.loop.firstApple){n.loop.firstApple=true;n.loop.level=Math.max(BALANCE.progression.firstHarvestLevel,n.loop.level);}if(!putInBag(n,'seed-'+p.seedKind))return fail('보관함이 가득 찼어요. 먼저 판매해 주세요.');return{ok:true,state:n,earned:v.reward,harvested:{id:'seed-'+p.seedKind,count:1}};}}
 else if(e.type==='wear'){if(!CLOSET[e.slot]?.includes(e.value))return fail('아직 없는 코디예요.');n.outfit[e.slot]=e.value;n.tasks.dressed=true;}
 else if(e.type==='look-save'){n.looks=[structuredClone(n.outfit),...n.looks.filter(x=>JSON.stringify(x)!==JSON.stringify(n.outfit))].slice(0,4);}
 else if(e.type==='look-load'){const look=n.looks[e.index];if(!look)return fail('저장한 코디가 없어요.');n.outfit=structuredClone(look);}
 else if(e.type==='walk'){if(!route(s,s.avatar,e.to).length)return fail('그쪽으로 가는 길이 없어요.');n.avatar=e.to;}
 else if(e.type==='place'||e.type==='move'){const kind=e.type==='move'?p?.kind:e.kind;if(!FURNITURE[kind]||!validCell(e.c,e.r))return fail('잔디 안의 빈 자리를 골라 주세요.');if(n.items.some(x=>x.c===e.c&&x.r===e.r&&x.id!==p?.id)||(n.animals||[]).some(a=>a.c===e.c&&a.r===e.r)||n.avatar[0]===e.c&&n.avatar[1]===e.r)return fail('물건이나 내가 있는 자리예요.');if(e.type==='place'&&n.items.filter(x=>x.kind===kind).length>=limit(n,kind))return fail('주머니의 물건을 모두 놓았어요. 조개 상점에서 더 살 수 있어요.');const item=e.type==='move'?p:{id:n.next++,kind,rot:0};item.c=e.c;item.r=e.r;if(e.type==='place')n.items.push(item);if(![[0,1],[1,0],[-1,0],[0,-1]].some(([dc,dr])=>passable(n,n.avatar[0]+dc,n.avatar[1]+dr)))return fail('걸어 다닐 길을 한 칸 남겨 주세요.');n.tasks.decorated=true;}
 else if(e.type==='rotate'){if(!p)return fail('물건을 골라 주세요.');p.rot=1-p.rot;}
 else if(e.type==='store'){if(!p)return fail('물건을 골라 주세요.');if(p.seed||p.crop||p.seedKind)return fail('심은 화분과 텃밭은 옮겨 주세요. 작물을 지우지 않아요.');n.items=n.items.filter(x=>x.id!==p.id);}
 else if(e.type==='buy'){if(!FURNITURE[e.kind])return fail('없는 물건이에요.');if((n.extra[e.kind]||0)>=MAX_EXTRA)return fail('더 이상 살 수 없어요.');n.extra[e.kind]=(n.extra[e.kind]||0)+1;}
 else if(e.type==='adopt'){if(n.loop.level<BALANCE.progression.livestockUnlockLevel)return fail('가축은 섬 레벨 '+BALANCE.progression.livestockUnlockLevel+'부터 입양할 수 있어요.');if(!LIVESTOCK[e.kind])return fail('없는 동물이에요.');if(n.animals.length>=MAX_ANIMALS)return fail('이 섬의 목장이 가득 찼어요.');if(!passable(n,e.c,e.r)||n.avatar[0]===e.c&&n.avatar[1]===e.r)return fail('동물이 지낼 빈 잔디가 없어요. 섬을 넓혀 주세요.');n.animals.push({id:n.next++,kind:e.kind,c:e.c,r:e.r,at:now,stage:1,fed:false});n.tasks.ranched=true;}
 else if(e.type==='collect'){const a=n.animals.find(x=>x.id===e.id);if(!a||Math.abs(s.avatar[0]-a.c)+Math.abs(s.avatar[1]-a.r)!==1)return fail('먼저 동물 가까이 가 주세요.');if(!productReady(a,now))return fail(LIVESTOCK[a.kind].product+'이(가) 아직 준비 중이에요.');a.at=now;a.fed=false;n.tasks.ranched=true;if(!putInBag(n,'product-'+a.kind))return fail('보관함이 가득 찼어요. 먼저 판매해 주세요.');return{ok:true,state:n,earned:LIVESTOCK[a.kind].shells,harvested:{id:'product-'+a.kind,count:1}};}
 else if(['plant','water','fill','harvest','sit','sow','reap'].includes(e.type)){
 if(!p||Math.abs(s.avatar[0]-p.c)+Math.abs(s.avatar[1]-p.r)!==1)return fail('먼저 물건 가까이 가 주세요.');
 if(e.type==='plant'){if(p.kind!=='pot'||p.seed||!SEEDS[e.seed])return fail('빈 화분을 골라 주세요.');p.seed=e.seed;p.planted=now;p.boost=0;p.watered=0;n.tasks.planted=true;}
 if(e.type==='water'){if(p.kind!=='pot'||!p.seed)return fail('씨앗을 심은 화분에 물을 주어요.');if(growth(p,now)>=1){if(!n.flowers.includes(p.seed))n.flowers.push(p.seed);return{ok:true,state:n,why:'도감에 꽃을 기록했어요.'};}if(p.watered&&now-p.watered<7000)return fail('물이 스며들고 있어요. 잠시 쉬어 주세요.');p.watered=now;p.boost=(p.boost||0)+30000;n.tasks.watered=true;}
 if(e.type==='fill'){if(p.kind!=='bowl')return fail('물그릇을 골라 주세요.');n.water=true;n.tasks.filled=true;}
 if(e.type==='harvest'){if(p.kind!=='tree')return fail('사과나무를 골라 주세요.');if(n.fruitAt&&now-n.fruitAt<60000)return fail('다음 사과가 익고 있어요.');if(!putInBag(n,'apple'))return fail('보관함이 가득 찼어요. 먼저 판매해 주세요.');n.fruitAt=now;n.tasks.harvested=true;}
 if(e.type==='sit'){if(!['bench','cushion'].includes(p.kind))return fail('앉을 자리를 골라 주세요.');n.tasks.rested=true;}
 if(e.type==='sow'){if(p.kind!=='field'||p.crop||!CROPS[e.crop])return fail('빈 텃밭을 골라 주세요.');p.crop=e.crop;p.sown=now;n.tasks.sowed=true;}
 if(e.type==='reap'){if(p.kind!=='field'||!p.crop)return fail('작물을 심은 텃밭을 골라 주세요.');if(!ripe(p,now))return fail(CROPS[p.crop].name+'이(가) 아직 자라는 중이에요.');const earned=CROPS[p.crop].shells,harvested={id:'crop-'+p.crop,count:1};if(!putInBag(n,harvested.id))return fail('보관함이 가득 찼어요. 먼저 판매해 주세요.');delete p.crop;delete p.sown;n.tasks.reaped=true;return{ok:true,state:n,earned,harvested};}}
 else if(e.type==='pet'){if(n.petAt&&now-n.petAt<10000)return fail('모모가 가르릉거리며 쉬고 있어요.');n.petAt=now;n.hearts=Math.min(10,n.hearts+1);n.tasks.friend=true;}
 else if(e.type==='theme'){if(!['day','sunset'].includes(e.value))return fail('없는 풍경이에요.');n.theme=e.value;}
 else if(e.type==='welcome')n.welcomed=true;else return fail('아직 할 수 없어요.');return{ok:true,state:n};}
// On sky islands an item whose tile disappeared (new terrain or expansion) moves to the nearest free tile;
// with no room left it returns to the pocket (furniture is an allowance, nothing is lost).
function relocate(s,c,r){const free=terrainCells().filter(([x,y])=>!s.items.some(p=>p.c===x&&p.r===y)&&!s.animals.some(a=>a.c===x&&a.r===y));if(free.length<=6)return null;return free.sort((a,b)=>Math.hypot(a[0]-c,a[1]-r)-Math.hypot(b[0]-c,b[1]-r))[0];}
// New or unreadable saves start from the default layout fitted onto the current terrain.
const startState=()=>terrain?restore(JSON.stringify(fresh())):fresh();
export function restore(raw){try{const d=JSON.parse(raw);if(d?.v!==1||!Array.isArray(d.items)||d.items.length>75)return startState();const s=fresh();s.loop={v:1,started:d.loop?.started===true,firstApple:d.loop?.firstApple===true,starterId:Number.isSafeInteger(d.loop?.starterId)&&d.loop.starterId>0?d.loop.starterId:null,level:Math.max(1,Math.min(10,Math.floor(Number(d.loop?.level))||1))};s.feedStock=Object.fromEntries(Object.keys(FEED).map(k=>[k,Math.max(0,Math.min(999999,Math.floor(Number(d.feedStock?.[k]))||0))]));s.inventory=d.inventory?cleanBag(d.inventory):freshBag();if(Number.isSafeInteger(d.apples)&&d.apples>0)putInBag(s,'apple',Math.min(999999,d.apples));s.seedStock=seedCounts(d.seedStock);s.items=[];s.animals=[];const ids=new Set();const extra=d.extra&&typeof d.extra==='object'?d.extra:{};s.extra=Object.fromEntries(Object.keys(FURNITURE).filter(k=>Number.isSafeInteger(extra[k])&&extra[k]>0).map(k=>[k,Math.min(MAX_EXTRA,extra[k])]));
 for(const a of Array.isArray(d.animals)?d.animals.slice(0,MAX_ANIMALS):[]){if(!LIVESTOCK[a?.kind]||!Number.isSafeInteger(a.id)||a.id<1||ids.has(a.id)||!Number.isFinite(a.at))continue;let cell=[a.c,a.r];if(!validCell(...cell)||s.animals.some(x=>x.c===cell[0]&&x.r===cell[1])){if(!terrain)continue;cell=relocate(s,a.c,a.r);if(!cell)continue;}ids.add(a.id);s.animals.push({id:a.id,kind:a.kind,c:cell[0],r:cell[1],at:a.at,stage:animalStage(a),...(Number.isFinite(a.petAt)&&a.petAt>0?{petAt:a.petAt}:{}),fed:a.fed===true});}
 for(const p of d.items){if(p.kind==='seedplot'&&(!SEED_CATALOG[p.seedKind]||!Number.isFinite(p.seedAt)))continue;if(!FURNITURE[p.kind]||!Number.isSafeInteger(p.id)||p.id<1||ids.has(p.id)||s.items.filter(x=>x.kind===p.kind).length>=limit(s,p.kind))continue;let cell=[p.c,p.r];if(!validCell(...cell)||s.items.some(x=>x.c===cell[0]&&x.r===cell[1])||s.animals.some(a=>a.c===cell[0]&&a.r===cell[1])){if(!terrain)continue;cell=relocate(s,p.c,p.r);if(!cell)continue;}ids.add(p.id);s.items.push({id:p.id,kind:p.kind,c:cell[0],r:cell[1],rot:p.rot===1?1:0,...(p.kind==='pot'&&SEEDS[p.seed]&&Number.isFinite(p.planted)?{seed:p.seed,planted:p.planted,boost:Math.max(0,Math.min(90000,Number(p.boost)||0)),watered:Number(p.watered)||0}:{}),...(p.kind==='seedplot'&&SEED_CATALOG[p.seedKind]&&Number.isFinite(p.seedAt)?{seedKind:p.seedKind,seedAt:p.seedAt,seedBoost:Math.max(0,Math.min(SEED_CATALOG[p.seedKind].ms,Number(p.seedBoost)||0)),seedWatered:Number(p.seedWatered)||0}:{}),...(p.kind==='field'&&CROPS[p.crop]&&Number.isFinite(p.sown)?{crop:p.crop,sown:p.sown}:{})});}s.next=Math.max(0,...ids)+1;if(Array.isArray(d.avatar)&&passable(s,...d.avatar))s.avatar=d.avatar;else{const cells=terrainCells().filter(c=>passable(s,...c));s.avatar=(terrain?cells[Math.floor(cells.length/2)]:cells[0])||[4,7];}for(const k in CLOSET)if(CLOSET[k].includes(d.outfit?.[k]))s.outfit[k]=d.outfit[k];s.looks=Array.isArray(d.looks)?d.looks.slice(0,4).filter(x=>Object.keys(CLOSET).every(k=>CLOSET[k].includes(x[k]))):[];s.flowers=Array.isArray(d.flowers)?d.flowers.filter(x=>SEEDS[x]):[];s.hearts=Math.max(0,Math.min(10,Math.floor(Number(d.hearts)||0)));for(const k of ['petAt','fruitAt'])s[k]=Math.max(0,Number(d[k])||0);s.water=d.water===true;s.welcomed=d.welcomed===true;s.theme=d.theme==='sunset'?'sunset':'day';s.tasks=d.tasks&&typeof d.tasks==='object'?Object.fromEntries(Object.entries(d.tasks).filter(([k,v])=>['dressed','decorated','planted','watered','filled','harvested','rested','friend','sowed','reaped','ranched'].includes(k)&&v===true)):{};return s;}catch{return startState();}}

// The painted sprout to the character's right is the free starter apple.
// Move only the old automatic starter; preserve its growth and every other item.
export function initializeLoop(s,level=1,now=Date.now()){
 const n=structuredClone(s);n.loop.level=Math.max(n.loop.level,Math.min(10,level));
 const available=([c,r])=>passable(n,c,r)&&(c!==n.avatar[0]||r!==n.avatar[1])&&approach(n,n.avatar,{c,r}).length;
 const existing=n.items.find(p=>p.id===n.loop.starterId&&p.seedKind==='apple');
 if(existing){n.loop.started=true;return n;}
 // Repair missing starter identities on existing islands too, without resetting any crop.
 const legacy=n.items.find(p=>p.seedKind==='apple'&&((p.c===7&&p.r===16)||(p.c===STARTER_CELL[0]&&p.r===STARTER_CELL[1])));
 if(legacy){if(level===1&&!n.loop.firstApple&&legacy.c===7&&legacy.r===16&&available(STARTER_CELL))[legacy.c,legacy.r]=STARTER_CELL;n.loop.starterId=legacy.id;n.loop.started=true;return n;}
 const all=terrainCells(),xs=all.map(([c,r])=>c-r),ys=all.map(([c,r])=>c+r),targetX=Math.min(...xs)+(Math.max(...xs)-Math.min(...xs))*.76,targetY=Math.min(...ys)+(Math.max(...ys)-Math.min(...ys))*.56;
 const candidates=all.sort((a,b)=>Math.hypot(a[0]-a[1]-targetX,(a[0]+a[1]-targetY)*.8)-Math.hypot(b[0]-b[1]-targetX,(b[0]+b[1]-targetY)*.8));
 const cell=available(STARTER_CELL)?STARTER_CELL:candidates.find(available);
 if(!cell)return n;
 n.next=Math.max(n.next,1,...n.items.map(p=>p.id+1),...n.animals.map(a=>a.id+1));const id=n.next++;n.items.push({id,kind:'seedplot',seedKind:'apple',seedAt:now,seedBoost:0,seedWatered:0,c:cell[0],r:cell[1],rot:0});n.loop.started=true;n.loop.starterId=id;return n;
}
